def count_With_Odd_SetBits(n):
    """Write a python function to find number of integers with odd number of set bits.

    Count integers in the range 0 to ``n`` inclusive whose binary
    representation contains an odd number of set (1) bits. Since 0 has
    zero set bits, this is the same as counting from 1 to ``n``.
    """
    if n <= 0:
        return 0
    k = n.bit_length() - 1
    power = 1 << k
    rest = n - power
    # Numbers in [0, power - 1] contain exactly power // 2 integers
    # with an odd number of set bits (for power == 1 this is 0).
    # Numbers in [power, n] have the highest bit set, so their parity
    # is flipped relative to the corresponding numbers in [0, rest].
    return (power // 2) + (rest + 1 - count_With_Odd_SetBits(rest))
